"""Build the freestanding x64 and x86 input-thread helpers on native Windows."""

from __future__ import annotations

import argparse
import shutil
import subprocess
import sysconfig
import tempfile
from pathlib import Path

# Only the x86 helper needs import libraries generated by the x64 toolchain.
# These are documented WINAPI signatures; --kill-at keeps the exported DLL
# names undecorated while preserving stdcall stack sizes in linker symbols.
_IMPORTS = {
    "kernel32": {
        "DisableThreadLibraryCalls": 4,
        "FreeLibrary": 4,
        "LoadLibraryW": 4,
        "GetProcAddress": 8,
        "GetModuleHandleW": 4,
        "GetTickCount64": 0,
        "GetCurrentProcessId": 0,
        "GlobalGetAtomNameW": 12,
        "OpenFileMappingW": 12,
        "MapViewOfFile": 20,
        "UnmapViewOfFile": 4,
        "CloseHandle": 4,
        "Sleep": 4,
        "GetLastError": 0,
        "SetLastError": 4,
    },
    "user32": {
        "GetWindowThreadProcessId": 8,
        "GetThreadDesktop": 4,
        "IsWindowVisible": 4,
        "IsChild": 8,
        "OpenInputDesktop": 12,
        "GetUserObjectInformationW": 20,
        "CloseDesktop": 4,
        "GetForegroundWindow": 0,
        "GetGUIThreadInfo": 8,
        "GetKeyboardLayout": 4,
        "GetKeyboardLayoutList": 8,
        "ActivateKeyboardLayout": 8,
        "RegisterWindowMessageW": 4,
        "CallNextHookEx": 16,
        "SetWindowsHookExW": 16,
        "UnhookWindowsHookEx": 4,
        "PostMessageW": 16,
    },
    "ole32": {"CoCreateInstance": 20},
    "imm32": {
        "ImmGetContext": 4,
        "ImmGetOpenStatus": 4,
        "ImmGetCompositionStringW": 16,
        "ImmGetConversionStatus": 12,
        "ImmReleaseContext": 8,
    },
}


def _x86_libraries(directory: Path) -> None:
    dlltool = shutil.which("dlltool")
    if dlltool is None:
        raise RuntimeError("Building Windows input support requires MinGW-w64 dlltool")
    for library, procedures in _IMPORTS.items():
        definition = directory / f"{library}.def"
        definition.write_text(
            "EXPORTS\n"
            + "".join(f"{name}@{size}\n" for name, size in procedures.items()),
            encoding="ascii",
        )
        subprocess.run(
            [
                dlltool,
                "--machine",
                "i386",
                "--as-flags=--32",
                "--kill-at",
                "--dllname",
                f"{library}.dll",
                "--input-def",
                str(definition),
                "--output-lib",
                str(directory / f"lib{library}.a"),
            ],
            check=True,
        )


def build(source: Path, output: Path) -> tuple[Path, Path]:
    platform = sysconfig.get_platform().replace("-", "_")
    if not platform.startswith(("win_amd64", "mingw_x86_64")):
        raise RuntimeError("Building Windows input support requires native x64 Python")
    compiler = shutil.which("gcc")
    if compiler is None:
        raise RuntimeError("Building Windows input support requires MinGW-w64 GCC")
    output.mkdir(parents=True, exist_ok=True)
    libraries = ("kernel32", "user32", "ole32", "imm32")
    paths = []
    for bits in (64, 32):
        target = output / f"input-thread-{bits}.dll"
        command = [
            compiler,
            f"-m{bits}",
            "-shared",
            "-nostdlib",
            "-fno-builtin",
            "-fno-exceptions",
            "-fno-rtti",
            "-fno-stack-protector",
            "-fno-tree-loop-distribute-patterns",
            "-O2",
            "-Wall",
            "-Wextra",
            "-Werror",
            "-Wl,--enable-stdcall-fixup",
            "-Wl,--add-stdcall-alias",
            f"-Wl,--entry,{'DllMain' if bits == 64 else '_DllMain@12'}",
            str(source),
            "-o",
            str(target),
        ]
        with tempfile.TemporaryDirectory(prefix="docking-input-imports-") as temporary:
            if bits == 32:
                _x86_libraries(Path(temporary))
                command.append(f"-L{temporary}")
            command.extend(f"-l{name}" for name in libraries)
            subprocess.run(command, check=True)
        paths.append(target)
    return paths[0], paths[1]


def main() -> None:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--source", type=Path, required=True)
    parser.add_argument("--output", type=Path, required=True)
    args = parser.parse_args()
    build(args.source, args.output)


if __name__ == "__main__":
    main()
